package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import java.util.concurrent.atomic.*;
public class ChapterLoopTest extends Instrumentation {
    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier condition,String message)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){AtomicBoolean done=new AtomicBoolean();ui(()->done.set(condition.getAsBoolean()));if(done.get())return;Thread.sleep(40);}throw new AssertionError(message);}
    void repeat(MainActivity a,int chapter,int count)throws Exception{int[] goal={0};ui(()->goal[0]=a.completedBooks+count);await(()->{check(a.playing,"playback stopped: "+a.status.getText());check(a.chapter==chapter,"played another chapter: "+a.chapter);check(a.position>=a.chapters.get(chapter).start&&a.position<a.chapters.get(chapter).end,"position left loop chapter");return a.completedBooks>=goal[0];},"chapter did not repeat");}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();MainActivity activity=null;boolean passed=false;SharedPreferences preferences=getTargetContext().getSharedPreferences("reading_settings",0);boolean had=preferences.contains("loopPlayback"),old=preferences.getBoolean("loopPlayback",false);try{
        activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","chapter_loop_qa").putExtra("book_name","单章循环验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.offlineReady&&a.system.initialized,"voices not ready");
        ui(()->{a.stop();a.text="第一章 开始\n读书。\n第二章 中间\n听书。\n第三章 结束\n你好。\n";a.chapters=MainActivity.parse(a.text);a.readingLanguage="";a.systemVoiceKey="";a.offlineVoice=1000;a.rate=2;a.position=a.chapters.get(1).start;a.showPosition(true);a.loopPlayback=false;a.playbackMode.performClick();check(a.playbackMode.getText().toString().equals("单章循环"),"mode label unclear");a.startReading();});repeat(a,1,3);result.putBoolean("localMiddleChapterThreeLoops",true);
        ui(()->a.jump(2));repeat(a,2,2);result.putBoolean("manualNextUpdatesLoopTarget",true);ui(()->a.playbackMode.performClick());await(()->!a.playing&&a.latestStatus.equals("全书朗读完毕"),"sequence did not finish");
        ui(()->{a.position=0;a.showPosition(true);a.startReading();a.playbackMode.performClick();});repeat(a,0,2);ui(a::stop);result.putBoolean("switchDuringPlaybackClearsFutureChapters",true);
        ui(()->{SystemSpeaker.Option voice=a.system.offlineVoice("zh","");check(voice!=null,"Chinese system offline voice missing");a.systemVoiceKey=voice.key;a.position=a.chapters.get(1).start;a.showPosition(true);a.startReading();});repeat(a,1,2);ui(a::stop);result.putBoolean("systemMiddleChapterLoop",true);result.putString("result","PASS: only middle chapter loops; local 3 natural cycles; system 2 natural cycles; next chapter changes loop target; sequence finishes; enabling loop during playback clears future chapters");passed=true;
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}SharedPreferences.Editor restore=preferences.edit();if(had)restore.putBoolean("loopPlayback",old);else restore.remove("loopPlayback");restore.commit();getTargetContext().getSharedPreferences("reader_chapter_loop_qa",0).edit().clear().commit();}finish(passed?-1:0,result);}
}
